import strawberry
from strawberry.file_uploads import Upload
from strawberry.types import Info

@strawberry.type
class TaxFormResult:
    vendor_id: str
    document_id: str
    status: str

@strawberry.type
class Mutation:
    @strawberry.mutation
    async def attach_vendor_tax_form(
        self,
        info: Info,
        vendor_id: str,
        document: Upload
    ) -> TaxFormResult:
        user = info.context.get("current_user")
        if not user:
            raise Exception("Unauthenticated")

        vendor_service = info.context["vendor_service"]
        vendor = await vendor_service.get_vendor(vendor_id)
        if not vendor or vendor.owner_user_id != user.id:
            raise Exception("Vendor not found or access denied")

        raw_data = await document.read()
        doc_record = await vendor_service.store_tax_document(
            vendor_id=vendor_id,
            filename=document.filename,
            file_bytes=raw_data
        )

        return TaxFormResult(
            vendor_id=vendor_id,
            document_id=doc_record.id,
            status="SUBMITTED"
        )
